       if (body.tailscaleUrl !== undefined && typeof body.tailscaleUrl !== 'string') throw badRequest('Tailscale address must be a string')\n            const nextTailscaleUrl = body.tailscaleUrl === undefined ? gatewayState.tailscaleUrl :\n              body.tailscaleUrl.trim() ? normalizePublicUrl(body.tailscaleUrl.trim(), req, wsPath) : ''\n            if (nextTailscaleUrl && (new URL(nextTailscaleUrl).protocol !== 'ws:' || !isTailscaleIp(new URL(nextTailscaleUrl).hostname)))\n              throw badRequest('Tailscale address must use ws:// with a Tailscale IPv4 or IPv6 address')\n            gatewayState.setConnection(body.route, nextSettings, nextUrl, nextTailscaleUrl)\n            transportSettings = nextSettings\n            pairingRoute = body.route\n            rtc.configure(transportSettings)\n            log(`connection preference saved: route=${pairingRoute}; existing connections retained`)\n            sendJson(res, 200, { pairingRoute, p2pUrl: gatewayState.p2pUrl, tailscaleUrl: gatewayState.tailscaleUrl, webrtc: rtc.snapshot() })\n          } else if (req.method === 'POST' && p === '/mgw/cloudflare') {\n            const body = await readBody(req)\n            await tunnel.configure(body)\n            if (body.enabled && gatewayMode !== 'persistent') setGatewayMode('persistent', 'Cloudflare Tunnel enabled from management UI')\n            await tunnel.reconcile()\n            sendJson(res, 200, { ...tunnel.snapshot(), gatewayEnabled, gatewayMode })\n          } else if (req.method === 'POST' && p === '/mgw/cloudflare/check') {\n            await tunnel.checkEndpoint()\n            sendJson(res, 200, { ...tunnel.snapshot(), gatewayEnabled, gatewayMode })\n          } else if (req.method === 'POST' && p === '/mgw/cloudflare/restart') {\n            await tunnel.restart()\n            sendJson(res, 200, { ...tunnel.snapshot(), gatewayEnabled, gatewayMode })\n          } else if (req.method === 'POST' && p === '/mgw/auth') {\n            const body = await